LEGACY_RECORDS = [{'source': '/Users/cora/Documents/GitHub/lean-llm-opt/benchmark_dataset/Variant24/inputs/neighborhood_demand.csv', 'values': {'Neighborhood': 'N1', 'Demand': '28'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/benchmark_dataset/Variant24/inputs/neighborhood_demand.csv', 'values': {'Neighborhood': 'N2', 'Demand': '32'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/benchmark_dataset/Variant24/inputs/neighborhood_demand.csv', 'values': {'Neighborhood': 'N3', 'Demand': '44'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/benchmark_dataset/Variant24/inputs/neighborhood_demand.csv', 'values': {'Neighborhood': 'N4', 'Demand': '36'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/benchmark_dataset/Variant24/inputs/neighborhood_demand.csv', 'values': {'Neighborhood': 'N5', 'Demand': '52'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/benchmark_dataset/Variant24/inputs/neighborhood_demand.csv', 'values': {'Neighborhood': 'N6', 'Demand': '41'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/benchmark_dataset/Variant24/inputs/neighborhood_demand.csv', 'values': {'Neighborhood': 'N7', 'Demand': '25'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/benchmark_dataset/Variant24/inputs/neighborhood_demand.csv', 'values': {'Neighborhood': 'N8', 'Demand': '48'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/benchmark_dataset/Variant24/inputs/neighborhood_demand.csv', 'values': {'Neighborhood': 'N9', 'Demand': '55'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/benchmark_dataset/Variant24/inputs/neighborhood_demand.csv', 'values': {'Neighborhood': 'N10', 'Demand': '30'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/benchmark_dataset/Variant24/inputs/facility_distance.csv', 'values': {'Facility': 'F1', 'N1': '2', 'N2': '3', 'N3': '5', 'N4': '9', 'N5': '10', 'N6': '11', 'N7': '13', 'N8': '14', 'N9': '15', 'N10': '12'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/benchmark_dataset/Variant24/inputs/facility_distance.csv', 'values': {'Facility': 'F2', 'N1': '4', 'N2': '2', 'N3': '3', 'N4': '8', 'N5': '9', 'N6': '10', 'N7': '12', 'N8': '13', 'N9': '14', 'N10': '11'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/benchmark_dataset/Variant24/inputs/facility_distance.csv', 'values': {'Facility': 'F3', 'N1': '9', 'N2': '8', 'N3': '4', 'N4': '2', 'N5': '3', 'N6': '5', 'N7': '9', 'N8': '10', 'N9': '11', 'N10': '7'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/benchmark_dataset/Variant24/inputs/facility_distance.csv', 'values': {'Facility': 'F4', 'N1': '10', 'N2': '9', 'N3': '6', 'N4': '3', 'N5': '2', 'N6': '3', 'N7': '8', 'N8': '9', 'N9': '10', 'N10': '6'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/benchmark_dataset/Variant24/inputs/facility_distance.csv', 'values': {'Facility': 'F5', 'N1': '13', 'N2': '12', 'N3': '10', 'N4': '8', 'N5': '7', 'N6': '6', 'N7': '2', 'N8': '3', 'N9': '4', 'N10': '5'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/benchmark_dataset/Variant24/inputs/facility_distance.csv', 'values': {'Facility': 'F6', 'N1': '12', 'N2': '11', 'N3': '8', 'N4': '7', 'N5': '6', 'N6': '5', 'N7': '5', 'N8': '4', 'N9': '3', 'N10': '2'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/benchmark_dataset/Variant24/inputs/planning_parameters.csv', 'values': {'Parameter': 'NumberOfFacilitiesToOpen', 'Value': '2'}}]
import gurobipy as gp
from gurobipy import GRB
records = LEGACY_RECORDS
neighborhood_demand_records = [r for r in records if r['source'].endswith('neighborhood_demand.csv')]
neighborhoods = [r['values']['Neighborhood'] for r in neighborhood_demand_records]
demand = {}
for r in neighborhood_demand_records:
    n = r['values']['Neighborhood']
    d = r['values']['Demand']
    try:
        demand[n] = int(d)
    except Exception:
        raise ValueError(f'Invalid demand for neighborhood {n}: {d}')
facility_distance_records = [r for r in records if r['source'].endswith('facility_distance.csv')]
facilities = [r['values']['Facility'] for r in facility_distance_records]
distance = {}
for r in facility_distance_records:
    i = r['values']['Facility']
    distance[i] = {}
    for j in neighborhoods:
        if j not in r['values']:
            raise ValueError(f'Missing distance from facility {i} to neighborhood {j}')
        try:
            distance[i][j] = float(r['values'][j])
        except Exception:
            raise ValueError(f"Invalid distance from facility {i} to neighborhood {j}: {r['values'][j]}")
planning_param_records = [r for r in records if r['source'].endswith('planning_parameters.csv')]
p = None
for r in planning_param_records:
    if r['values'].get('Parameter') == 'NumberOfFacilitiesToOpen':
        try:
            p = int(r['values']['Value'])
        except Exception:
            raise ValueError(f"Invalid number of facilities to open: {r['values']['Value']}")
if p is None:
    raise ValueError('Number of facilities to open not found in planning_parameters.csv')
for i in facilities:
    if i not in distance:
        raise ValueError(f'Missing distance data for facility {i}')
    for j in neighborhoods:
        if j not in distance[i]:
            raise ValueError(f'Missing distance from facility {i} to neighborhood {j}')
for j in neighborhoods:
    if j not in demand:
        raise ValueError(f'Missing demand for neighborhood {j}')
m = gp.Model('p_median')
x_vars = m.addVars(facilities, neighborhoods, vtype=GRB.BINARY, name='')
y_vars = m.addVars(facilities, vtype=GRB.BINARY, name='')
m.setObjective(gp.quicksum((demand[j] * distance[i][j] * x_vars[i, j] for i in facilities for j in neighborhoods)), GRB.MINIMIZE)
m.addConstrs((gp.quicksum((x_vars[i, j] for i in facilities)) == 1 for j in neighborhoods), name='')
m.addConstr(gp.quicksum((y_vars[i] for i in facilities)) == p, name='open')
m.addConstrs((x_vars[i, j] <= y_vars[i] for i in facilities for j in neighborhoods), name='')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for v in m.getVars():
        print(f'{v.VarName}: {v.X}')
else:
    print(f'Solver status: {m.Status}')